MAP='''<svg viewBox="0 0 900 420" role="img" aria-label="Условная схема: исторический кампус у улицы Мира и отдельный район Новокольцовский. Не географическая карта."><rect width="900" height="420" rx="16" fill="#e9eddc"/><path d="M70 110h470M280 40v340M100 300h400M600 80v280" stroke="#fffef9" stroke-width="28"/><path d="M540 210h150" stroke="#07584b" stroke-width="2" stroke-dasharray="8 8"/><text x="60" y="55" fill="#172321" font-size="21" font-family="Arial">ВТУЗГОРОДОК</text><text x="610" y="55" fill="#172321" font-size="21" font-family="Arial">НОВОКОЛЬЦОВСКИЙ</text><rect x="310" y="150" width="160" height="100" rx="8" fill="#07584b"/><text x="330" y="190" fill="#fff" font-size="18" font-family="Arial">Мира, 19</text><text x="330" y="220" fill="#fff" font-size="15" font-family="Arial">Главный корпус</text><rect x="80" y="155" width="160" height="85" rx="8" fill="#b9a9ed"/><text x="100" y="195" fill="#172321" font-size="18" font-family="Arial">Мира, 32</text><text x="100" y="220" fill="#172321" font-size="15" font-family="Arial">Радиофак</text><rect x="640" y="140" width="200" height="130" rx="8" fill="#d5f64b"/><text x="655" y="180" fill="#172321" font-size="17" font-family="Arial">100-летия УрГУ, 6/2</text><text x="655" y="210" fill="#172321" font-size="15" font-family="Arial">Оформление</text><text x="655" y="234" fill="#172321" font-size="15" font-family="Arial">проживания НВК</text><text x="60" y="385" fill="#172321" font-size="15" font-family="Arial">Условная схема · без масштаба · не используется для навигации</text></svg>'''
checkitems=['Паспорт','Договор найма и ордер','Медицинские документы','Квитанция об оплате','Фотографии для оформления','Дополнительные соглашения']
page('campus.html','Ближе к своему.',f'''<div class="section-head"><h2>Кампус —<br>тоже дом.</h2><p>Собрали шаги поселения и документы в одном месте. Конкретное общежитие укажут в ордере.</p></div><div class="campus-map">{MAP}</div>{source('https://privet.urfu.ru/navigation','Адреса учебных корпусов')}{source('https://privet.urfu.ru/accommodation','Адрес службы НВК и порядок поселения')}<div class="split" style="margin-top:48px"><section><h2 style="font-size:48px">Как заселиться.</h2><ol class="step-list" style="margin-top:32px"><li><h3>Пройдите медосмотр</h3><p>Уточните необходимые обследования и документы в медсанчасти УрФУ.</p></li><li><h3>Получите договор и ордер</h3><p>За выдачу отвечает институт. Проверьте информацию у ответственного за поселение.</p></li><li><h3>Оплатите проживание</h3><p>Код платежа указан в ордере; обеспечительный платёж — в дополнительном соглашении.</p></li><li><h3>Оформите регистрацию</h3><p>Адрес паспортного отдела зависит от общежития. Сверьте его в официальном навигаторе.</p></li><li><h3>Придите в общежитие</h3><p>Возьмите договор, ордер, медицинские документы и подтверждение оплаты.</p></li></ol>{source('https://privet.urfu.ru/accommodation','Поселение · Навигатор первокурсника')}</section><section><div class="card bg-lime"><h3>Что взять с собой</h3><p>Отмечайте собранное. Чек-лист сохраняется на этом устройстве, если браузер разрешает локальное хранение.</p><div class="checklist full-width">{''.join(f'<label class="check"><input type="checkbox" data-checklist="move-{i}">{s}</label>' for i,s in enumerate(checkitems))}</div>{source('https://privet.urfu.ru/accommodation','Документы на поселение')}</div><div class="notice"><h3>Сколько стоит?</h3><p style="margin-top:12px">Актуальный приказ о стоимости проживания не получен. Месяц — <strong>—</strong>, год — <strong>—</strong>. Размещение вдвоём или втроём и расстояние до института нужно уточнить.</p><a href="contacts.html">Помочь с вопросом ↗</a></div><button class="btn btn-outline" data-print>Распечатать маршрут</button></section></div><section id="cost" class="section"><h2>Считаем честно.</h2><p class="lead" style="margin-block:24px">Калькулятор стоимости обучения. Проживание не включаем, пока нет подтверждённого тарифа.</p><div class="calc-panel"><label class="field"><span>Программа</span><select id="cost-program">{''.join(f'<option value="{p["id"]}">{E(p["name"])} · {p["code"]}</option>' for p in P)}</select></label><label class="check"><input type="checkbox" id="cost-discount">Показать опубликованную цену со скидкой, если она есть</label><p class="small muted">Право на скидку и её сохранение на следующих курсах уточняйте отдельно.</p><div id="cost-result" class="calc-result" aria-live="polite"></div>{source()}<small class="source">Итог за весь срок — арифметическая оценка при неизменной годовой цене, не сумма договора. Общежитие: данных нет.</small></div></section>''',color='bg-orange',desc='Условная схема кампусов, порядок поселения, документы и калькулятор известных расходов.')
# STUDENT
studentcards=[('Расписание','Посмотреть пример недели и сохранить группу.','schedule.html'),('Баллы и БРС','Как устроена балльно-рейтинговая система.','account.html'),('Стипендии','Виды поддержки и опубликованные базовые суммы.','student.html#money'),('Справки','Демо-заявка на справку об обучении.','account.html#requests'),('Пропуск и IT','Официальный маршрут к цифровым сервисам.','student.html#it'),('Кампус и спорт','Корпуса, общежития и места для занятий.','campus.html')]
page('student.html','Учиться. Жить.<br>Успевать.',f'''<div class="grid-3">{''.join(card(t,s,h,'Открыть', ['bg-lime','bg-purple','bg-pink'][i%3]) for i,(t,s,h) in enumerate(studentcards))}</div><section id="money" class="section"><h2>Поддержка рядом.</h2><p class="lead" style="margin-block:24px">Государственная академическая стипендия: опубликованные базовые суммы без уральского районного коэффициента.</p><div class="grid-3"><div class="card"><p>Первый курс, до первой аттестации</p><strong class="dashboard-number">2 314,2 ₽</strong><p>В месяц. Для очных бюджетников бакалавриата, специалитета и базового высшего образования.</p>{source('https://privet.urfu.ru/money','Стипендии · 2026')}</div><div class="card"><p>После первой аттестации</p><strong class="dashboard-number">3 008,2 ₽</strong><p>В месяц. При соблюдении требований к результатам сессии.</p>{source('https://privet.urfu.ru/money','Стипендии · 2026')}</div><div class="card"><p>Для отличников</p><strong class="dashboard-number">4 398 ₽</strong><p>В месяц. Условия назначения проверяйте в официальном навигаторе.</p>{source('https://privet.urfu.ru/money','Стипендии · 2026')}</div></div></section><div class="split"><section id="it"><h2 style="font-size:48px">Цифровой минимум.</h2>{faq('Где мой настоящий личный кабинет?',f'На официальных сервисах УрФУ. {ext("https://privet.urfu.ru/it","Открыть инструкции по IT-сервисам")}. Наш кабинет — демонстрация без настоящей авторизации.')}{faq('Как получить пропуск?',f'Электронный пропуск выдаёт дирекция института. При неисправности обратитесь в бюро пропусков; документы уточните в {ext("https://privet.urfu.ru/accommodation","официальной инструкции")}.')}{faq('Где библиотека?',f'Начните с раздела {ext("https://privet.urfu.ru/education","«Учёба» официального навигатора")}. Он ведёт к Зональной научной библиотеке.')}</section><section><h2 style="font-size:48px">Первокурснику.</h2>{faq('Что такое БРС?','Балльно-рейтинговая система: результаты работы по дисциплине оцениваются в баллах. Условия и распределение баллов задаются по конкретной дисциплине.')}{faq('Что такое дирекция института?','Команда, к которой обращаются с организационными вопросами обучения. Контакты можно найти через официальный сайт своего института.')}{faq('Если нужна психологическая помощь?','Начните с контакт-центра университета: попросите актуальный контакт психологической службы. Непроверенный телефон мы не публикуем.')}</section></div>''',color='bg-purple',desc='Сервисный центр студента: расписание, поддержка, пропуск, справки и первые шаги.')
# ACCOUNT
page('account.html','Ваш учебный день.',f'''<span class="demo-badge">ДЕМО · НЕТ ПОДКЛЮЧЕНИЯ К ДАННЫМ СТУДЕНТОВ</span><div class="notice">Вход не требует логина или пароля. Все оценки, занятия и заявки ниже — вымышленные примеры интерфейса.</div><div class="grid-3"><div class="card bg-lime"><span class="tag">ПРИМЕР</span><h3>Ближайшая пара</h3><strong class="dashboard-number">10:40</strong><p>Проектный практикум<br>Аудитория Р-237 — демонстрационный код</p><a class="text-link" href="schedule.html">Всё расписание ↗</a></div><div class="card"><span class="tag">ПРИМЕР БРС</span><h3>Математика</h3><strong class="dashboard-number">76 / 100</strong><div class="brs full-width" role="img" aria-label="Пример: 76 из 100 баллов"><span></span></div><p>Демо-шкала, не официальная ведомость.</p></div><div class="card bg-pink"><span class="tag">ПРИМЕР</span><h3>Без долгов</h3><strong class="dashboard-number">0</strong><p>Учебных задолженностей в демо-кабинете. Реальные сведения — в официальной системе.</p></div></div><div class="split" style="margin-top:40px"><section class="card" id="requests"><h3>Справка без похода по кабинетам</h3><p>Демо-заявка остаётся только в браузере и никуда не отправляется.</p><form id="certificate-form" class="full-width"><label class="field"><span>Какая справка нужна?</span><select name="certificate"><option>Об обучении</option><option>О стипендии</option></select></label><button class="btn">Создать демо-заявку ↗</button></form><div id="certificate-result" role="status"></div></section><section class="card bg-purple"><h3>Мой первый месяц</h3><div class="checklist full-width">{''.join(f'<label class="check"><input type="checkbox" data-checklist="first-{i}">{s}</label>' for i,s in enumerate(['Узнать номер группы','Получить пропуск','Найти свою аудиторию','Разобраться с библиотекой','Познакомиться с одногруппниками']))}</div></section></div>''',desc='Демонстрация личного кабинета: учебный день, баллы и заявки. Без настоящих персональных данных.')
# SCIENCE / LIFE / PARTNERS
page('science.html','Вопросы становятся<br>открытиями.',f'''<div class="split"><section><h2>Любопытство —<br>ваша отправная точка.</h2><p class="lead" style="margin-block:24px">Начните с научной темы в программе, которая вас увлекает. Затем найдите руководителя и спросите о студенческих проектах.</p>{btn('Найти программу и руководителя','catalog.html')}</section><img src="assets/images/campus-1.webp" width="1400" height="933" loading="lazy" alt="Обсуждение проекта в УрФУ" style="border-radius:20px"></div><div class="grid-3" style="margin-top:48px">{card('Космос и наблюдения','В программе «Астрономия» указаны практики на базе Коуровской астрономической обсерватории.','Program.html?id=10037','Изучить программу','bg-purple')}{card('Цифровые технологии','Найдите программы в области IT, математики и инженерии и посмотрите опубликованные описания проектов.','catalog.html?area=IT+%D0%B8+%D0%BC%D0%B0%D1%82%D0%B5%D0%BC%D0%B0%D1%82%D0%B8%D0%BA%D0%B0','Выбрать направление','bg-lime')}{card('Ваш первый шаг','Напишите руководителю выбранной программы. Кратко расскажите об интересах и спросите, как присоединиться к работе.','contacts.html','Как связаться','bg-pink')}</div><section class="section prose"><h2>Как войти в проект.</h2><ol><li>Выберите тему и прочитайте описание программы.</li><li>Найдите опубликованное имя руководителя.</li><li>Уточните действующие лаборатории, задачи и требования к участникам.</li></ol><p>Перечень текущих грантов и конкурсов не получен. Проверяйте сроки на официальном портале: закрытые конкурсы здесь не выдаются за действующие.</p>{source('https://programs.edu.urfu.ru/ru/10037/','Программа «Астрономия» · 2026')}{ext('https://urfu.ru/ru/science/','Научные направления на сайте УрФУ')}</section>''',color='bg-green',desc='Найдите тему, команду и первый шаг в исследованиях УрФУ.')
page('life.html','Больше, чем пары.',f'''<div class="feature-story bg-pink" style="border-radius:20px;overflow:hidden"><div><div class="eyebrow">ВАШЕ ВРЕМЯ БЫТЬ СОБОЙ</div><h2>НАЙДИТЕ<br>СВОИХ.</h2><p class="lead">Университет — место, где пробуют новое и находят людей с похожими интересами. Начните с официального навигатора студенческих организаций.</p>{ext('https://privet.urfu.ru/orgs','Студенческие организации УрФУ ↗')}</div><div style="padding:0"><img src="assets/images/p4.webp" width="1200" height="800" loading="lazy" alt="Выпускники УрФУ на ступенях университета"></div></div><div class="grid-3" style="margin-top:32px">{card('Спорт','В официальном навигаторе указаны манеж на Мира, 29 и комплекс игровых видов спорта на Станислава Набойченко, 14.','campus.html','Сориентироваться','bg-lime')}{card('Своя команда','Выберите сообщество по интересам и проверьте, как к нему присоединиться, в официальном разделе организаций.','contacts.html','Нужна помощь?','bg-purple')}{card('Не пропустить важное','Проверьте новости университета и официальные объявления. Для событий с неизвестной датой напоминания не создаём.','events.html','Открыть афишу','bg-orange')}</div>{source('https://privet.urfu.ru/navigation','Спортивные корпуса')}{source('https://privet.urfu.ru/orgs','Студенческие организации')}''',color='bg-pink',desc='Спорт, сообщества, творчество и ваш круг людей в УрФУ.')
page('partners.html','Большие дела —<br>вместе.',f'''<div class="grid-3">{card('Практика и проекты','Предложите задачу студентам и обсудите формат работы с профильным институтом. Начните с образовательной программы.','catalog.html','Найти профиль','bg-lime')}{card('Целевое обучение','Условия договора, обязательства и меры поддержки должны быть опубликованы заказчиком. Проверяйте действующие правила приёма.','admission.html','Маршрут поступления','bg-purple')}{card('Научное сотрудничество','Сформулируйте задачу, ожидаемый результат и необходимые компетенции. Университет поможет найти профильную команду.','contacts.html','Начать разговор','bg-pink')}</div><section class="section prose"><h2>С чего начать разговор.</h2><p>Опишите задачу простыми словами: что нужно решить, для кого и в какой срок. Укажите, нужен ли вам исследовательский проект, практика студентов или консультация.</p><p>Обратитесь в контакт-центр и попросите направить запрос в профильное подразделение. Неподтверждённые контакты менеджеров мы не публикуем.</p>{btn('8 800 100-50-44','tel:88001005044')}{source('https://privet.urfu.ru/','Контакт-центр УрФУ')}</section>''',color='bg-orange',desc='Найдите образовательную или исследовательскую команду под вашу задачу.')
# NEWS
page('news.html','УрФУ в движении.',f'<div class="grid-3">{news_cards()}</div><div class="grid-3" style="margin-top:40px">'+''.join(card(E(n['title']),E(n['text'][:220]),'article.html?id='+n['id'],'Читать') for n in NEWS[3:])+'</div>'+source('https://rtf.urfu.ru/get-news/ru/?rows=2&cols=3&pid=18511&offset=0','Официальная лента ИРИТ-РТФ'),color='bg-purple',desc='Новости из официальной ленты института: с датой и ссылкой на источник.')
page('article.html','История из УрФУ.',f'<article id="article-content" class="prose"><p>Выберите новость в ленте.</p>{btn("Открыть новости","news.html")}</article>',color='bg-purple',desc='Краткая новость по материалам официальной ленты ИРИТ-РТФ.')
page('events.html','Найдётся повод.',f'''<div class="tabs" id="event-filters" role="group" aria-label="События для вашей роли"><button aria-pressed="true" data-event-role="all">Всем</button><button aria-pressed="false" data-event-role="applicant">Поступающим</button><button aria-pressed="false" data-event-role="student">Студентам</button></div><div class="empty" id="event-list" role="status"><h3>Пока нет подтверждённых будущих событий</h3><p>Мы не выдаём архивные мероприятия за актуальные. Как только появятся официальные даты, здесь будет афиша.</p>{ext('https://rtf.urfu.ru/ru/','Проверить объявления института ↗')}</div><div class="notice">В источнике есть объявление встречи для абитуриентов на 3 июля 2026 года. Оно уже прошло и не попадает в будущую афишу.{source('https://rtf.urfu.ru/get-news/ru/?rows=2&cols=3&pid=18511&offset=0','Лента ИРИТ-РТФ · новость от 30.06.2026')}</div>''',color='bg-orange',desc='Только события с подтверждёнными датами. Прошедшие встречи не маскируются под будущие.')
# CONTACTS / SEARCH
services=[{'name':'Контакт-центр УрФУ','keys':'вопрос поступление приёмка справка психолог помощь общежитие стипендия','text':'Начните здесь, если не знаете, какая служба нужна. Часы работы в доступном источнике не указаны.','phone':'8 800 100-50-44','href':'tel:88001005044','source':'https://privet.urfu.ru/'},{'name':'Поселение в общежитие','keys':'кампус общага заселение договор ордер','text':'Ответственный за поселение вашего института выдаёт документы. Контакты институтов собраны в официальной инструкции.','href':'https://privet.urfu.ru/accommodation','source':'https://privet.urfu.ru/accommodation'},{'name':'Стипендии и материальная поддержка','keys':'стипуха деньги стипендия выплаты','text':'Виды выплат и условия назначения — в разделе «За деньги — да» официального навигатора.','href':'https://privet.urfu.ru/money','source':'https://privet.urfu.ru/money'},{'name':'Пропуск и цифровые сервисы','keys':'вайфай wifi кабинет интернет пропуск','text':'Инструкции для личного кабинета, Wi-Fi и интернета в общежитиях.','href':'https://privet.urfu.ru/it','source':'https://privet.urfu.ru/it'}]
(R/'data/services.js').write_text('window.URFU_SERVICES = '+json.dumps(services,ensure_ascii=False)+';')
contacts_html=''.join(f'<article class="card service-card" data-service="{E(s["name"]+" "+s["keys"])}"><h3>{s["name"]}</h3><p>{s["text"]}</p>'+ (f'<a class="text-link" href="{s["href"]}">{s["phone"]} ↗</a>' if 'phone'in s else ext(s['href'],'Открыть официальную инструкцию ↗'))+source(s['source'],'Навигатор УрФУ')+'</article>' for s in services)
page('contacts.html','Давайте разберёмся.',f'''<label class="field" style="max-width:700px"><span>С чем нужна помощь?</span><input id="service-query" type="search" placeholder="Например, общежитие или стипендия"></label><p id="service-count" class="small" style="margin-bottom:24px" aria-live="polite">Выберите подходящий маршрут ниже.</p><div class="grid-2" id="service-list">{contacts_html}</div><div class="empty" id="service-empty" hidden><h3>Такую службу пока не нашли</h3><p>Позвоните в контакт-центр: 8 800 100-50-44. Помогут определить нужное подразделение.</p></div><section class="section" id="faq"><h2>Частые вопросы.</h2><p class="lead" style="margin-block:24px">Помощник по готовой базе ответов. Без внешнего ИИ и без передачи вашего запроса.</p><label class="field"><span>Ваш вопрос</span><input id="faq-query" type="search" placeholder="Как заселиться? Где расписание?"></label><div id="faq-results" aria-live="polite">{faq('Как узнать стоимость программы?', 'Откройте каталог, выберите программу и посмотрите цену из официального источника. Цена нового набора может отличаться.')}{faq('Как заселиться в общежитие?','Начните с ответственного за поселение в своём институте. Он сообщит порядок получения договора и ордера.')}{faq('Где настоящее расписание?',f'В официальных сервисах УрФУ. {ext("https://privet.urfu.ru/education","Открыть навигатор по учебным сервисам")}. Расписание нашего прототипа — демо.')}{faq('Где уточнить условия стипендии?',f'В {ext("https://privet.urfu.ru/money","официальном разделе стипендий")}. Суммы зависят от оснований и результатов обучения.')}</div></section>''',color='bg-pink',desc='Найдите нужную службу по своему вопросу — без знания структуры университета.')
page('search.html','Один поиск.<br>Все ответы.',f'''<form action="search.html" id="search-form" style="max-width:900px"><label class="field" for="site-query"><span>Что вы хотите найти?</span></label><div class="search-field">{icon('search')}<input id="site-query" name="q" type="search" placeholder="Попробуйте «общага»" autocomplete="off" data-suggest><button aria-label="Искать">{icon('arrow')}</button></div></form><p class="small muted" style="margin-top:16px">Понимает «общага», «стипуха», «пары», е/ё и простые опечатки.</p><div class="tabs" id="search-tabs" role="group" aria-label="Тип результата"></div><p id="search-count" aria-live="polite"></p><div id="search-results" class="search-results"><p>Введите запрос. Ищем по страницам, программам, службам и новостям.</p></div>''',desc='Поиск по программам, страницам, службам и новостям УрФУ. Понимает привычные слова.',extra='<script src="data/services.js" defer></script>')
# ABOUT
page('about.html','Урал. Характер.<br>Будущее.',f'''<div class="split"><section><h2>История продолжается.<br>Теперь — с вами.</h2><p class="lead" style="margin-block:24px">Уральский федеральный университет объединяет разные области знаний и людей, которые хотят менять мир вокруг себя.</p>{btn('Найти свой маршрут','quiz.html')}</section><div class="timeline"><article><strong>1920</strong><h3>Начало истории</h3><p>Основан Уральский государственный университет.</p>{source('https://privet.urfu.ru/about','История университета')}</article><article><strong>2009</strong><h3>Федеральный университет</h3><p>В официальном навигаторе эта дата указана как создание УрФУ на базе УГТУ-УПИ и УрГУ.</p>{source('https://privet.urfu.ru/about','История университета')}</article><article><strong>2023</strong><h3>Новый кампус</h3><p>Открыт кампус в Новокольцовском районе Екатеринбурга.</p>{source('https://privet.urfu.ru/about','История университета')}</article></div></div><section class="section"><h2>Люди и связи.</h2><div class="grid-2" style="margin-top:32px"><div class="card"><h3>Ректор</h3><p>Обабков Илья Николаевич</p><p>Мира, 19 · ГУК-300</p><a href="mailto:rector@urfu.ru">rector@urfu.ru</a>{source('https://privet.urfu.ru/about','Люди университета · 2026')}</div>{card('Документы и сведения','Обязательная информация и официальные документы доступны на действующем портале УрФУ.','contacts.html','Нужна помощь?')}</div></section>''',color='bg-green',desc='История университета, люди и официальные источники. От первого шага до общего будущего.')
# CONCEPT
page('concept.html','Свой маршрут.',f'''<div class="prose"><p class="lead">Университет, в котором легко найти следующий шаг.</p><div class="tabs"><a class="btn" href="docs/urfu-design-project.pdf">Дизайн-проект · PDF ↗</a><a class="btn btn-outline" href="docs/urfu-walkthrough-60s.mp4">Видео · 60 секунд ↗</a></div><h2>От структуры — к задаче.</h2><p>Поступающий не обязан знать, какой институт ведёт программу. Студент не должен искать расписание среди новостей. Поэтому сайт начинает разговор с того, что человек хочет сделать.</p><h3>Принципы</h3><ol><li>Задача человека важнее названия подразделения.</li><li>Известные данные — рядом с источником. Неизвестные — с честной отметкой.</li><li>Один поиск по программам, страницам, службам и вопросам.</li><li>Доступность, мобильный экран и офлайн — часть основы.</li></ol><h2>Что подтверждено исследованием.</h2><p>Официальные данные распределены по отдельным ресурсам: каталог программ, навигатор первокурсника и сайт института. В прототипе основные маршруты объединены. Само наличие разных доменов не доказывает плохое качество — мы оцениваем конкретный путь пользователя.</p><p>Главный портал urfu.ru во время сбора вернул HTTP 403. Поэтому точное число ссылок и кликов на старой главной не измерено. Мы не публикуем придуманные сравнения.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Таблица с горизонтальной прокруткой"><table><caption>Целевые маршруты нового прототипа; сравнение со старым сайтом ещё не измерено</caption><thead><tr><th scope="col">Задача</th><th scope="col">Маршрут в прототипе</th><th scope="col">Старый сайт</th></tr></thead><tbody>{''.join(f'<tr><th scope="row">{a}</th><td>{b}</td><td>Не измерено</td></tr>' for a,b in [('Найти программу','Главная → каталог'),('Узнать стоимость','Каталог → программа'),('Найти аудиторию','Главная → код аудитории'),('Открыть расписание','Нижняя панель → группа'),('Подготовиться к поселению','Кампус → чек-лист'),('Узнать стипендию','Студенту → поддержка'),('Найти службу','Поиск → контакт'),('Поделиться подборкой','Каталог → поделиться')])}</tbody></table></div><h2>Как внедрять.</h2><ol><li>Запустить бета-версию рядом с действующим сайтом. Проверить задачи с поступающими и студентами.</li><li>Согласовать владельцев данных и подключить официальные выгрузки каталога и расписания.</li><li>Подключить единый вход через официального провайдера. Демо-кабинет заменить реальными данными только после согласования доступа.</li><li>Переносить разделы по одному. Для каждого адреса сохранить переадресацию, документы и поисковую доступность.</li><li>Выдать редакции единый шаблон с проверкой дат, источников и обязательных полей. Сохранять историю обновлений цен.</li></ol><h2>Как проверяем.</h2><p>Открытие через file:// и локальный HTTP, клавиатурные сценарии, ширины от 320 px, отсутствие внешних запросов, фильтры в адресе, пустые состояния, режим reduced-motion и цветовые схемы.</p><p>Измерения PageSpeed Insights для опубликованного сайта ещё не выполнены. Оценки скорости и доступности не заявлены. Стандарт WCAG 2.2 AA — цель; автоматическая проверка не заменяет ручной аудит.</p><h2>Что ещё требует данных.</h2><ul><li>Проходные баллы прошлых лет.</li><li>Календарь и достижения для приёма 2027 года.</li><li>Актуальные приказы о ценах общежитий.</li><li>Подтверждённые поэтажные планы и будущие события.</li></ul><h2 id="sources">Источники.</h2><p>Снимок собран 25 октября 2026 года. Учебный набор — 2026, если не указано иное.</p><ul><li>{ext(DATA['source'],'Официальный каталог программ — выбранные уровень и форма')}</li><li>{ext('https://privet.urfu.ru/','Навигатор первокурсника')}</li><li>{ext('https://privet.urfu.ru/navigation','Адреса корпусов')}</li><li>{ext('https://privet.urfu.ru/money','Стипендии')}</li><li>{ext('https://privet.urfu.ru/accommodation','Поселение')}</li><li>{ext('https://privet.urfu.ru/about','История и руководство')}</li><li>{ext('https://rtf.urfu.ru/ru/','Новости и фотографии ИРИТ-РТФ')}</li></ul><p>Сборщик программ: <a href="scripts/collect.py" download>collect.py</a>. Данные: <a href="data/catalogue.json" download>каталог с источниками</a>. Источники фотографий: <a href="docs/assets.md">реестр материалов</a>.</p><h2>Визуальный язык.</h2><p>Малахитовый — опора. Лаймовый — следующий шаг. Розовый и аметистовый — энергия разных маршрутов. Стрелка связывает знак «У», навигацию и оформление страниц.</p>{btn('Логотип и фирменный стиль','style.html')}</div>''',color='bg-pink',desc='Идея конкурсного прототипа, принципы, источники, ограничения и план внедрения.')
# BRAND
page('style.html','Узнаваемый характер.',f'''<div class="split"><div><h2>Знак,<br>который ведёт.</h2><p class="lead" style="margin-block:24px">Буква «У» становится развилкой маршрута. Наклонная грань повторяется в фотографиях и стрелках.</p><p>Это конкурсная интерпретация, не утверждённый фирменный знак университета.</p></div><div class="logo-demo bg-lime">{logo()}</div></div><div class="grid-2" style="margin-top:24px"><div class="logo-demo bg-green">{logo()}</div><div class="logo-demo bg-purple">{MARK}</div></div><section class="section"><h2>Уральская палитра.</h2><div class="grid-3" style="margin-top:32px">{''.join(f'<div class="swatch {c}">{s}<br>{hex}</div>' for c,s,hex in [('bg-green','Малахит','#07584B'),('bg-lime','Новый рост','#D5F64B'),('bg-pink','Родонит','#F3A6CA'),('bg-purple','Аметист','#B9A9ED'),('bg-orange','Тёплая яшма','#FF956D'),('bg-ink','Тёмный камень','#172321')])}</div></section><div class="split"><section class="prose"><h2>Шрифт — это голос.</h2><h3>Oswald · заголовки</h3><p>Крупный, плотный, плакатный. С кириллицей и латиницей.</p><h3>Golos Text · текст</h3><p>Спокойный и читаемый в длинных описаниях и интерфейсах. Файлы находятся внутри проекта; внешние шрифтовые сервисы не используются.</p><p>Лицензия обоих шрифтов — SIL Open Font License. Копии лицензий приложены к файлам.</p></section><section class="prose"><h2>Правила знака.</h2><p>Охранное поле — не меньше ширины основного штриха. Минимальная высота в интерфейсе — 32 px; это правило проекта, не официальный стандарт УрФУ.</p><p>Не растягивайте, не поворачивайте и не добавляйте тени к знаку. Не размещайте его на пёстром фоне без однотонной подложки.</p><p>В светлой версии — тёмный знак. На малахитовом и почти чёрном фоне — светлый. Форма остаётся одинаковой.</p><a class="text-link" href="assets/logo.svg" download>Скачать SVG ↗</a></section></div>''',color='bg-purple',desc='Знак, палитра, типографика и правила использования конкурсного визуального стиля.')
page('404.html','Кажется, свернули.',f'''<p class="lead">Такой страницы в прототипе нет. Вернёмся к вашему вопросу?</p><div class="tabs">{btn('На главную','index.html')}{btn('Найти ответ','search.html','btn-outline')}{btn('Каталог программ','catalog.html','btn-outline')}</div>''',color='bg-pink',desc='Поможем вернуться на маршрут: поиск, главная и каталог.')
# ENGLISH
page('index.html','Your path.<br>Your UrFU.',f'''<div class="split"><section><h2>A big future.<br>A clear next step.</h2><p class="lead" style="margin:24px 0">Explore official degree information and find your way into Ural Federal University.</p>{btn('Explore programs','catalog.html')}{source(DATA['source'],'Official UrFU catalogue · 2026',True)}</section><img src="../assets/images/p4.webp" width="1200" height="800" alt="UrFU graduates outside the university" style="border-radius:20px"></div><div class="grid-3" style="margin-top:40px">{card('Find your program','Full-time bachelor and specialist programs from the official 2026 catalogue.','catalog.html','Explore programs','bg-purple')}{card('Plan your application','Check requirements for your citizenship and qualification with the university.','admission.html','Start here','bg-pink')}{card('Ask a question','Contact the university for confirmed dates, tuition and admission details.','contacts.html','Get in touch','bg-lime')}</div><p class="notice">Independent contest prototype. This website does not accept applications or personal documents.</p>''',color='bg-green',desc='Find your next step at Ural Federal University. Official sources, clear admissions routes.',en=True)
page('admission.html','Your next chapter.',f'''<div class="prose"><h2>Start with a program.</h2><ol><li>Explore the degree programs and teaching requirements.</li><li>Confirm admission rules for your citizenship and qualifications.</li><li>Check the application calendar on the official university website.</li><li>Apply only through the university’s official channels.</li></ol><p>Verified dates for the 2027 intake are unavailable in this snapshot. We do not reuse dates from a previous year.</p><p>International tuition and entry requirements may differ. Fees in our program catalogue are published for Russian citizens and are not a personal quotation.</p>{btn('Explore programs','catalog.html')}<p style="margin-top:24px">{ext('https://urfu.ru/en/','Official university website')}</p></div>''',color='bg-orange',desc='A clear route to official admission information for international applicants.',en=True)
english=[p for p in P if p.get('enName')]
page('catalog.html','Find your direction.',f'''<div class="notice">Official English titles are available for {len(english)} of {len(P)} programs in this snapshot. Programs without a verified English title are omitted. Fees are for Russian citizens; international fees must be confirmed separately.{source(DATA['source'],'Official UrFU catalogue · 2026',True)}</div><label class="field"><span>Search programs</span><input id="en-catalog-query" type="search" placeholder="For example, engineering"></label><p id="en-count" aria-live="polite" style="margin-bottom:24px">{len(english)} programs</p><div class="program-grid" id="en-programs">{''.join('<article class="program-card"><span class="tag">'+p['code']+'</span><h3>'+E(p['enName'])+'</h3><p class="small">Full-time · 2026 intake</p>'+f'<p>Annual tuition for Russian citizens: {p["price"]:,} ₽</p>' if False else '' for p in [])}{''.join(f'<article class="program-card" data-en-name="{E(p["enName"].lower())}"><span class="tag">{p["code"]} · {"Specialist" if p["level"]=="специалитет" else "Bachelor"}</span><h3>{E(p["enName"])}</h3><p class="small">Full-time · 2026 intake</p><p class="small">Previous passing score: unavailable</p>{ext(p["englishSource"],"Official English program page ↗")}{source(p["englishSource"],"UrFU · 2026",True)}</article>' for p in english)}</div>''',color='bg-purple',desc='Verified English titles from the official UrFU degree catalogue.',en=True)
page('contacts.html','Let’s talk.',f'''<div class="grid-2"><section class="card bg-lime"><h3>University contact centre</h3><a class="text-link" href="tel:88001005044">8 800 100-50-44 ↗</a><p>This toll-free number is published for calls within Russia. International availability and office hours are not confirmed.</p>{source('https://privet.urfu.ru/','Official student navigator',True)}</section><section class="card"><h3>International applicants</h3><p>Use the official English portal for admissions contacts and requirements. We do not publish unverified contact details.</p>{ext('https://urfu.ru/en/','Official English portal ↗')}</section></div>''',color='bg-pink',desc='Official contact routes for Ural Federal University.',en=True)
page('international.html','Make UrFU<br>your next step.',f'''<div class="prose"><p class="lead">Explore verified English program titles and find the official route to international admissions.</p><div class="tabs">{btn('English website','en/index.html')}{btn('Degree programs','en/catalog.html','btn-outline')}</div><p>This is an independent contest prototype. Current visa requirements, application deadlines and international fees must be confirmed with the university.</p>{ext('https://urfu.ru/en/','Official university website ↗')}</div>''',color='bg-purple',desc='An English route to programs, admissions information and official contacts.',en=False)
